using System.Diagnostics;
using System.Globalization;
using System.Text;
using System.Text.Json;
using RideHailing.Messaging.Contracts;

namespace RideHailing.Messaging.Outbox;

public enum OutboxStatus
{
    Pending,
    Published,
    FailedVisible,
}

/// <summary>
/// One durable Outbox intent. The message identity is fixed at creation and is
/// never regenerated by a relay: an uncertain publish republishes the same id.
/// </summary>
public sealed record OutboxMessage
{
    public required string MessageId { get; init; }
    public required string MessageType { get; init; }
    public required int SchemaVersion { get; init; }
    public required string CorrelationId { get; init; }
    public string? CausationId { get; init; }
    public string? AggregateType { get; init; }
    public string? AggregateId { get; init; }
    public long? AggregateVersion { get; init; }
    public string? SagaId { get; init; }
    public string? OperationKey { get; init; }
    public required string PayloadJson { get; init; }
    public required string HeadersJson { get; init; }
    public required string Exchange { get; init; }
    public required string RoutingKey { get; init; }
    public required DateTimeOffset OccurredAt { get; init; }
    public OutboxStatus Status { get; init; } = OutboxStatus.Pending;
    public int AttemptCount { get; init; }
    public required DateTimeOffset NextAttemptAt { get; init; }
    public string? ClaimedBy { get; init; }
    public DateTimeOffset? ClaimedAt { get; init; }
    public DateTimeOffset? PublishedAt { get; init; }
    public string? LastErrorCode { get; init; }
    public DateTimeOffset? LastErrorAt { get; init; }

    public static OutboxMessage Create<T>(MessageEnvelope<T> envelope, string exchange, string routingKey,
        IDictionary<string, object?>? headers = null, DateTimeOffset? now = null)
    {
        envelope.Validate();
        if (string.IsNullOrWhiteSpace(exchange)) throw new ArgumentException("exchange is required");
        if (string.IsNullOrWhiteSpace(routingKey)) throw new ArgumentException("routingKey is required");

        var transportHeaders = new Dictionary<string, string>(StringComparer.Ordinal);
        if (headers is not null)
        {
            foreach (var (key, value) in headers)
            {
                if (string.IsNullOrWhiteSpace(key) || value is null) continue;
                transportHeaders[key] = HeaderValue(value);
            }
        }

        if (!transportHeaders.ContainsKey(TraceHeaderPropagation.TraceParentHeader))
        {
            var trace = new Dictionary<string, object?>();
            TraceHeaderPropagation.Inject(Activity.Current?.Context ?? default, trace);
            foreach (var (key, value) in trace)
                transportHeaders[key] = value?.ToString() ?? "";
        }

        var message = new OutboxMessage
        {
            MessageId = envelope.MessageId,
            MessageType = envelope.MessageType,
            SchemaVersion = envelope.SchemaVersion,
            CorrelationId = envelope.CorrelationId,
            CausationId = envelope.CausationId,
            AggregateType = envelope.AggregateType,
            AggregateId = envelope.AggregateId,
            AggregateVersion = envelope.AggregateVersion,
            SagaId = envelope.SagaId,
            OperationKey = envelope.OperationKey,
            PayloadJson = JsonSerializer.Serialize(envelope.Payload),
            HeadersJson = JsonSerializer.Serialize(transportHeaders),
            Exchange = exchange,
            RoutingKey = routingKey,
            OccurredAt = envelope.OccurredAt,
            NextAttemptAt = now ?? envelope.OccurredAt,
        };
        message.Validate();
        return message;
    }

    public MessageEnvelope<JsonElement> ToEnvelope()
    {
        using var document = JsonDocument.Parse(PayloadJson);
        var envelope = new MessageEnvelope<JsonElement>(
            MessageId, MessageType, SchemaVersion, OccurredAt, CorrelationId, CausationId,
            document.RootElement.Clone(), AggregateType, AggregateId, AggregateVersion, SagaId, OperationKey);
        envelope.Validate();
        return envelope;
    }

    public byte[] SerializeBody() => JsonSerializer.SerializeToUtf8Bytes(ToEnvelope());

    public Dictionary<string, object?> TransportHeaders()
    {
        var stored = JsonSerializer.Deserialize<Dictionary<string, string>>(HeadersJson)
            ?? new Dictionary<string, string>(StringComparer.Ordinal);
        return stored.ToDictionary(pair => pair.Key, pair => (object?)pair.Value, StringComparer.Ordinal);
    }

    public void Validate()
    {
        if (string.IsNullOrWhiteSpace(MessageId)) throw new ArgumentException("messageId is required");
        if (string.IsNullOrWhiteSpace(MessageType)) throw new ArgumentException("messageType is required");
        if (SchemaVersion != 1) throw new ArgumentException("Only schemaVersion 1 is supported");
        if (string.IsNullOrWhiteSpace(CorrelationId)) throw new ArgumentException("correlationId is required");
        if (string.IsNullOrWhiteSpace(Exchange)) throw new ArgumentException("exchange is required");
        if (string.IsNullOrWhiteSpace(RoutingKey)) throw new ArgumentException("routingKey is required");
        if (OccurredAt == default) throw new ArgumentException("occurredAt is required");
        if (NextAttemptAt == default) throw new ArgumentException("nextAttemptAt is required");
        if (AttemptCount < 0) throw new ArgumentException("attemptCount cannot be negative");
        if (!Enum.IsDefined(Status)) throw new ArgumentOutOfRangeException(nameof(Status));
        if (Status == OutboxStatus.Published && PublishedAt is null)
            throw new ArgumentException("publishedAt is required once published");
        if ((AggregateType is null) != (AggregateId is null))
            throw new ArgumentException("aggregateType and aggregateId must be supplied together");
        if (AggregateVersion < 0) throw new ArgumentException("aggregateVersion cannot be negative");
        if (AggregateVersion.HasValue && AggregateId is null)
            throw new ArgumentException("aggregateVersion requires aggregate identity");
        foreach (var field in new[] { CausationId, AggregateType, AggregateId, SagaId, OperationKey })
            if (field is not null && string.IsNullOrWhiteSpace(field))
                throw new ArgumentException("Optional identities must be omitted or nonblank");

        if (string.IsNullOrWhiteSpace(PayloadJson)) throw new ArgumentException("payload is required");
        using (var payload = JsonDocument.Parse(PayloadJson))
        {
            if (payload.RootElement.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined)
                throw new ArgumentException("payload is required");
        }

        _ = TransportHeaders();
    }

    public static string ToDatabase(OutboxStatus status) => status switch
    {
        OutboxStatus.Pending => "PENDING",
        OutboxStatus.Published => "PUBLISHED",
        OutboxStatus.FailedVisible => "FAILED_VISIBLE",
        _ => throw new ArgumentOutOfRangeException(nameof(status)),
    };

    public static OutboxStatus FromDatabase(string status) => status switch
    {
        "PENDING" => OutboxStatus.Pending,
        "PUBLISHED" => OutboxStatus.Published,
        "FAILED_VISIBLE" => OutboxStatus.FailedVisible,
        _ => throw new ArgumentOutOfRangeException(nameof(status), status, "Unknown Outbox status"),
    };

    private static string HeaderValue(object value) => value switch
    {
        string text => text,
        byte[] bytes => Encoding.UTF8.GetString(bytes),
        ReadOnlyMemory<byte> memory => Encoding.UTF8.GetString(memory.Span),
        _ => Convert.ToString(value, CultureInfo.InvariantCulture) ?? "",
    };
}
